"""Final topup of subjective questions for ch237 and ch238."""

from sqlalchemy import select
from app.db.session import SessionLocal
from app.models.curriculum import BloomLevel, LearningOutcome
from app.models.question import Question, QuestionDifficulty, QuestionStatus, QuestionType


def _options(q):
    return {"choices": list(q["options"])} if q.get("options") else None


def insert(db, ch, supp):
    om = {r.code: r.id for r in db.scalars(select(LearningOutcome).where(LearningOutcome.chapter_id == ch)).all()}
    ex = {r.text for r in db.scalars(select(Question).where(Question.chapter_id == ch)).all()}
    n = 0
    for q in supp:
        if q["question"] in ex: continue
        oc = q.get("outcome_code")
        db.add(Question(chapter_id=ch, topic_id=None, outcome_id=om.get(oc) if oc else None, outcome_code=oc,
            type=QuestionType(q["type"]), difficulty=QuestionDifficulty(q["difficulty"]), status=QuestionStatus.APPROVED,
            cognitive_level=BloomLevel(q["cognitive_level"].lower()), text=q["question"], options=_options(q),
            correct_answer=q["answer"], explanation=q.get("explanation"), marks=int(q.get("marks", 1)), created_by_id=14))
        n += 1
    db.commit()
    return n


